Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Abbreviation ASEGS := AsanUbsan.M.loaded_segments.
#[local] Abbreviation cellA := (cell AsanUbsan.M.loaded_segments).
#[local] Abbreviation wrA := (wr AsanUbsan.M.loaded_segments).
#[local] Notation "'U' r" := (bv_unsigned r) (at level 10, r at level 9).

Definition art_fi_mem (M : word -> option byte) (S : Z) (raw0 : word) (regs : bvmap 5 word) : word -> option byte := ltac2:(Rpl.RP.run_i (rplG ()) 4 "SA0!1,1|600;!1+00|30;|21;!1,13}8!1,72|40;|48;|31;!1,79|500;!1,7|42;!1,7|43;|44;!1,7>!1,7|45;$M;R%~R1!1+2!1+0!1,12$S;R+3$raw0;R1$regs;R!2'441!4'55!4'55!4'55!4'55!4'55!4'55!4'55#4!2'6#36!2'80#2!2'6#3!1,77!2'80!2'9#1!3,:46vv,;!2'<46!2'6#3!1,78!2'80!2'9#1!3,:4:vv,;!2'<4:!2'6#3!1,7;!2'80!2'9#1!3,:4<vv,;!2'<4<!2'6#3!1,7|508;!2'80!2'9#1!3,:4=vv,;!2'<4=!2'6#3!1,7|510;!2'80!2'9#1!3,:4?vv,;!2'<4?!2'6#3!1,7|518;!2'80!2'9#1!3,:4@vv,;!2'<4@").

Section FPX. Context {fx : PropExec.FPState}.

(* [comment removed for export] *)
Lemma art_fi_a_fn : forall regs (M rom : word -> option byte) (raw0 : word) (S p : Z),
  getr regs 1 = raw0 -> getr regs 2 = Z_to_bv 64 S -> getr regs 10 = Z_to_bv 64 p ->
  0x10007fff8000 + 8192 <= S -> S < 2 ^ 47 -> 0 <= p < 2 ^ 64 ->
  wrA M (S - 4096) 4096 ->
  msteps ASEGS (mkst regs (0x826a0 : word) M rom)
